import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    n = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1
    s = [int(data[idx + i]) for i in range(k)]
    win = [False] * (n + 1)
    for i in range(1, n + 1):
        for x in s:
            if x <= i and not win[i - x]:
                win[i] = True
                break
    if win[n]:
        for x in sorted(s):
            if x <= n and not win[n - x]:
                sys.stdout.write(\"WIN %d\\n\" % x)
                return
    sys.stdout.write(\"LOSE\\n\")

main()
